-- PT108-S2-Q1. Batch 06.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT108-S2-Q1$batch06$ AND q.stimulus=$batch06$Jorge: It is obvious that a shift in economic policy is needed, so why not proceed with the necessary changes all at once? If one wants to jump over a chasm, one would do it with one leap.

Christina: I disagree with your view, even though I agree that a shift in economic policy is needed. If one wants to teach a horse to jump fences, one should train it to jump lower heights first.$batch06$ AND q.prompt=$batch06$Jorge and Christina disagree over whether$batch06$ AND q.correct_choice=$batch06$D$batch06$) THEN RAISE EXCEPTION 'Question changed: PT108-S2-Q1'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch06$PT108-S2-Q1$batch06$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT108-S2-Q1'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT108-S2-Q1$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Jorge's Position$batch06$, $batch06$Make all the needed changes in economic policy at once, the way you would jump a chasm in one leap.$batch06$), (1, $batch06$Christina's Position$batch06$, $batch06$She agrees a shift is needed, but compares it to training a horse: start with lower jumps first.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$Christina says it out loud: she agrees a shift is needed. So that is common ground. The disagreement is about pace: all at once or step by step.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Whether the changes should all be made at once.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT108-S2-Q1$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$Christina explicitly agrees a shift is needed. So does Jorge.$batch06$), ($batch06$B$batch06$, $batch06$The horse analogy is Christina's. Jorge never addresses it.$batch06$), ($batch06$C$batch06$, $batch06$Neither speaker talks about how painful the changes would be.$batch06$), ($batch06$D$batch06$, $batch06$Jorge wants everything at once. Christina wants it gradual.$batch06$), ($batch06$E$batch06$, $batch06$Neither says how grave the situation is.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT108-S2-Q1$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
